from .tuner import (
    autotune,  # noqa: F401
    AutoTuner,  # noqa: F401
)
from .capture import (
    set_autotune_inputs,  # noqa: F401
    get_autotune_inputs,  # noqa: F401
)

config_args = []
for config in self.configs:
    new_kwargs = {}
    keys = config.keys()
    for name, _ in parameters.items():
        if name in config:
            new_kwargs[name] = config[name]
    unused_keys = set(keys) - set(new_kwargs.keys())
    if len(unused_keys) > 0:
        raise ValueError(f"Unused keys in config: {unused_keys}")
    config_args.append(new_kwargs)

if len(config_args) == 0:
    raise ValueError("No configurations to tune, please check your `@autotune` decorator")

# check if the tunable arguments has been set.
# get the back config argument
top_config, *rest = config_args

# Cache control API (wrap CacheState)
def is_cache_enabled(self) -> bool:
    return not self.is_cache_globally_disabled() and CacheState.is_enabled()

def enable_cache(self) -> None:
    CacheState.enable()

def disable_cache(self) -> None:
    CacheState.disable()

def is_cache_globally_disabled(self) -> bool:
    return self.TILELANG_DISABLE_CACHE.lower() in ("1", "true", "yes", "on")

def is_autotune_cache_disabled(self) -> bool:
    return self.TILELANG_AUTO_TUNING_DISABLE_CACHE.lower() in ("1", "true", "yes", "on")
